let activeRectoUiLocale = "zh-CN";

function normalizeRectoUiPreference(value) {
	return RECTO_UI_LANGUAGES.includes(value) ? value : "follow";
}

function resolveRectoUiLocale(preference, hostLanguage) {
	const selected = normalizeRectoUiPreference(preference);
	if (selected !== "follow") return selected;
	const tag = String(hostLanguage || "").trim().replace(/_/g, "-").toLowerCase();
	if (tag === "zh" || tag === "zh-cn" || tag === "zh-sg" || tag === "zh-my" || tag === "zh-hans" || tag.startsWith("zh-hans-")) return "zh-CN";
	if (tag.startsWith("zh-")) return "en";
	const base = tag.split("-")[0];
	return RECTO_UI_LANGUAGES.includes(base) ? base : "en";
}

function translateRectoUi(locale, key, params = {}) {
	const lang = resolveRectoUiLocale(locale, locale);
	const template = RECTO_UI_MESSAGES[lang][key] || RECTO_UI_MESSAGES.en[key] || "Text unavailable.";
	return template.replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (_, name) =>
		params[name] == null ? "—" : String(params[name]));
}

function rectoUiText(key, params) {
	return translateRectoUi(activeRectoUiLocale, key, params);
}

// Recto owns only its own notices; never patch Obsidian's global Notice class.
const rectoNoticeHistory = new Map();
function showRectoNotice(message, options = {}) {
	const text = String(message || "").trim();
	if (!text) return null;
	const tone = options.tone || "neutral";
	const duration = options.brief ? 2500 : ["attention", "error"].includes(tone) ? 7000 : 4000;
	const key = options.key || `${tone}:${text}`;
	const previous = rectoNoticeHistory.get(key);
	if (previous && Date.now() - previous.at < (options.dedupeMs ?? 1800)) return previous.notice;
	const notice = new obsidian.Notice(text, duration);
	const inner = notice.noticeEl;
	const outer = inner?.closest?.(".notice") || inner;
	if (outer?.classList) {
		outer.classList.add("recto-ui", "rc-notice");
		outer.dataset.tone = tone;
		outer.setAttribute("role", "status");
		outer.setAttribute("aria-live", "polite");
		outer.setAttribute("aria-atomic", "true");
		// No HTML interpolation, focus transfer or action controls in transient feedback.
		if (inner?.ownerDocument && inner.replaceChildren) {
			const icon = inner.ownerDocument.createElement("span");
			icon.className = "rc-icon rc-notice-icon"; icon.setAttribute("aria-hidden", "true");
			setChromeIcon(icon, ({ success: "check", attention: "triangle-alert", error: "circle-alert" })[tone] || "info");
			const body = inner.ownerDocument.createElement("span"); body.className = "rc-notice-text"; body.textContent = text;
			inner.classList.add("rc-notice-content"); inner.replaceChildren(icon, body);
		}
	}
	rectoNoticeHistory.set(key, { at: Date.now(), notice });
	for (const [id, item] of rectoNoticeHistory) if (Date.now() - item.at > 30000) rectoNoticeHistory.delete(id);
	return notice;
}

// Field feedback survives a local redraw, but never copies raw exception strings.
function bindRectoInlineFeedback(owner, key, container) {
	if (!container?.createDiv) return null;
	const targets = owner.rectoFeedbackTargets ||= new Map();
	const nodes = targets.get(key) || new Set(); targets.set(key, nodes);
	let node = [...nodes].find(item => container.contains?.(item));
	if (!node) {
		if (key === "results" && container.createEl) {
			const details = container.createEl("details", { cls: "rc-inline-feedback" });
			details.createEl("summary", { text: rectoUiText("notice.details") });
			node = details.createDiv(); node.rectoFeedbackWrapper = details;
		} else node = container.createDiv({ cls: "rc-inline-feedback" });
		node.setAttribute?.("role", "status"); node.setAttribute?.("aria-live", "polite");
		nodes.add(node);
	}
	const message = owner.rectoInlineFeedback?.get(key) || "";
	node.textContent = message; node.hidden = !message;
	if (node.rectoFeedbackWrapper) node.rectoFeedbackWrapper.hidden = !message;
	return node;
}
function setRectoInlineFeedback(owner, key, message) {
	(owner.rectoInlineFeedback ||= new Map()).set(key, String(message || ""));
	let targets = owner.rectoFeedbackTargets?.get(key);
	if (!targets || ![...targets].some(node => node.isConnected !== false)) {
		const container = owner.contentEl || owner.containerEl;
		if (container) bindRectoInlineFeedback(owner, key, container);
		targets = owner.rectoFeedbackTargets?.get(key);
	}
	for (const target of targets || []) {
		if (target.isConnected === false) { targets.delete(target); continue; }
		target.textContent = message || ""; target.hidden = !message;
		if (target.rectoFeedbackWrapper) target.rectoFeedbackWrapper.hidden = !message;
	}
}

function rectoTaskResultText(results, action = "convert") {
	if (!results.length || results.some(item => ["waiting", "pending"].includes(item.status))) return "";
	const completed = results.filter(item => item.status === "success").length;
	if (results.length === 1) {
		const item = results[0];
		if (item.status === "success") return rectoUiText(action === "translate" ? "notice.translateDone" : "notice.convertDone");
		if (item.status === "partial") return rectoUiText(item.partialKind === "summary" ? "notice.partialSummary" : item.partialKind === "summary-only" ? "notice.summaryOnly" : "notice.partialTranslation");
		return item.reason || rectoUiText("notice.taskFailed");
	}
	return completed === results.length
		? rectoUiText("notice.batchDone", { count: completed, action: documentLanguageText(action === "translate" ? "翻译" : "转换", action === "translate" ? "Translation" : "Conversion") })
		: rectoUiText("notice.batchPartial", { success: completed, incomplete: results.length - completed });
}

// Session summaries follow the original submission through deferred network/recovery
// callbacks. diagnosticItemId is already preserved by the task persistence contract.
class RectoNotificationBatches {
	constructor(plugin) { this.plugin = plugin; this.groups = new Map(); }
	snapshot() {
		return [...this.groups].map(([id, group]) => ({ id, action: group.action, skipped: group.skipped,
			items: [...group.items.values()].map(item => ({
				task: { recordId: item.task.recordId, diagnosticItemId: item.task.diagnosticItemId },
				status: item.status, partialKind: item.partialKind || "", reason: item.reason || "",
			})),
		}));
	}
	restore(saved) {
		const activeIds = new Set([...(this.plugin.localTaskIntents || []).map(item => this.identity(item.task)),
			...(this.plugin.pendingBackendTasks || []).map(item => this.identity(item.task || item))]);
		for (const group of Array.isArray(saved) ? saved : []) {
			if (typeof group?.id !== "string" || !["convert", "translate"].includes(group.action) || !Array.isArray(group.items)) continue;
			const items = group.items.filter(item => item?.task && typeof this.identity(item.task) === "string"
				&& ["waiting", "pending", "success", "partial", "failed"].includes(item.status)
				&& (!["waiting", "pending"].includes(item.status) || activeIds.has(this.identity(item.task))));
			if (items.some(item => activeIds.has(this.identity(item.task)))) this.groups.set(group.id, { action: group.action, skipped: Math.max(0, Number(group.skipped) || 0),
				items: new Map(items.map(item => [this.identity(item.task), item])), running: 0 });
		}
	}
	identity(task) { return task.diagnosticItemId || task.recordId || task.markdownPath; }
	register(id, tasks, skipped = 0) {
		this.groups.set(id, { action: tasks.some(task => task.translateOnly || this.plugin.wantsTranslationForTask?.(task)) ? "translate" : "convert",
			items: new Map(tasks.map(task => [this.identity(task), { task, status: "waiting" }])), skipped, running: 0 });
	}
	start(tasks) { for (const group of this.groups.values()) if (tasks.some(task => group.items.has(this.identity(task)))) group.running++; }
	record(result) {
		for (const group of this.groups.values()) if (group.items.has(this.identity(result.task))) group.items.set(this.identity(result.task), result);
	}
	endUnavailable(task, reason = rectoUiText("error.taskExpired")) {
		this.record({ task, status: "failed", reason }); this.flush();
	}
	finish(tasks, results = []) {
		for (const result of results) this.record(result);
		for (const group of this.groups.values()) if (tasks.some(task => group.items.has(this.identity(task)))) group.running = Math.max(0, group.running - 1);
		this.flush();
	}
	cancel(tasks) {
		for (const [id, group] of this.groups) {
			for (const task of tasks) group.items.delete(this.identity(task));
			if (!group.items.size) this.groups.delete(id);
		}
	}
	skip(tasks) {
		for (const group of this.groups.values()) for (const task of tasks) {
			if (group.items.delete(this.identity(task))) group.skipped++;
		}
	}
	flush() {
		for (const [id, group] of this.groups) {
			if (group.running) continue;
			const results = [...group.items.values()], message = rectoTaskResultText(results, group.action);
			if (!message) continue;
			this.groups.delete(id);
			showRectoNotice(message + (group.skipped ? `\n${rectoUiText("notice.skipped", { count: group.skipped })}` : ""), {
				tone: results.every(item => item.status === "success") ? "success" : results.every(item => item.status === "failed") ? "error" : "attention", key: `batch:${id}`,
			});
		}
	}
}
function createRectoUiError(key, params) {
	const error = new Error(rectoUiText(key, params));
	error.rectoUiKey = key;
	error.rectoUiParams = params || {};
	return error;
}
const RECTO_UI_ZH_STATIC_KEYS = new Map(Object.entries(RECTO_UI_MESSAGES["zh-CN"])
	.filter(([, value]) => !/\{[A-Za-z][A-Za-z0-9]*\}/.test(value))
	.map(([key, value]) => [value, key]));
const RECTO_UI_EN_STATIC_KEYS = new Map(Object.entries(RECTO_UI_MESSAGES.en)
	.filter(([, value]) => !/\{[A-Za-z][A-Za-z0-9]*\}/.test(value))
	.map(([key, value]) => [value, key]));

const PDF_CONFIRM_BYTES = 30 * 1024 * 1024;
const PDF_MAX_BYTES = 50 * 1024 * 1024; // 与后端 nginx client_max_body_size 50m 对齐，避免大文件上传被 413

// ═══════════════════════════════════════════════════════════════════
// HTTP helper (binary-safe)
// ═══════════════════════════════════════════════════════════════════

function resolveRectoHostNetwork() {
	// Electron net.fetch uses the host session/system proxy and supports real abort.
	// Resolve before sending; never replay a POST through a second transport.
	if (!process.versions?.electron) return null;
	try {
		const remote = require("electron").remote || require("@electron/remote");
		const Controller = remote.getGlobal("AbortController");
		if (typeof remote.net?.fetch === "function" && typeof Controller === "function") return { net: remote.net, Controller };
	} catch (_) {}
	throw Object.assign(new Error("Host network unavailable"), { code: "HOST_NETWORK_UNAVAILABLE", rectoUiKey: "error.hostNetwork" });
}

function requestRectoHostNetwork(host, url, method, body, headers, timeout, options) {
	return new Promise((resolve, reject) => {
		const parsed = new URL(url);
		if (!["https:", "http:"].includes(parsed.protocol)) throw new Error("Unsupported URL protocol");
		if (body && typeof body.pipe === "function") throw new Error("Host request requires a buffered body");
		const controller = new host.Controller();
		const maxBytes = Number(options.maxBytes) || 0;
		let settled = false, timer, status = null, reader;
		const cleanup = () => { clearTimeout(timer); options.signal?.removeEventListener("abort", onAbort); };
		const fail = error => {
			if (settled) return;
			settled = true; cleanup();
			if (status !== null) { error.httpStatus = status; error.responseReceived = true; }
			try { controller.abort(); } catch (_) {}
			try { if (reader) Promise.resolve(reader.cancel()).catch(() => {}); } catch (_) {}
			reject(error);
		};
		const onAbort = () => fail(new Error("任务已取消"));
		if (options.signal?.aborted) { onAbort(); return; }
		options.signal?.addEventListener("abort", onAbort, { once: true });
		const deadline = Number(options.deadlineMs) || Number(timeout) || 30000;
		timer = setTimeout(() => fail(Object.assign(new Error("Request deadline exceeded"), { code: "REQUEST_DEADLINE_EXCEEDED" })), deadline);
		timer.unref?.();
		const run = async () => {
			// Chromium sets framing and decodes gzip; never trust compressed length as
			// the decoded size limit. Explicit bearer headers survive credentials=omit.
			const cleanHeaders = Object.fromEntries(Object.entries(headers || {}).filter(([key]) => !/^(content-length|accept-encoding)$/i.test(key)));
			const response = await host.net.fetch(parsed.href, { method, headers: cleanHeaders, body: body == null ? undefined : body,
				signal: controller.signal, redirect: "error", credentials: "omit", cache: "no-store" });
			if (settled) return;
			status = response.status;
			const chunks = []; let total = 0;
			reader = response.body?.getReader();
			while (reader && !settled) {
				const chunk = await reader.read();
				if (settled) return;
				if (chunk.done) break;
				const bytes = Buffer.from(chunk.value); total += bytes.length;
				if (maxBytes && total > maxBytes) throw Object.assign(new Error("Response too large"), { code: "RESPONSE_TOO_LARGE" });
				chunks.push(bytes);
			}
			if (settled) return;
			const bodyBuffer = Buffer.concat(chunks);
			settled = true; cleanup();
			resolve({ status, bodyBuffer, bodyText: bodyBuffer.toString("utf-8") });
		};
		void run().catch(error => {
			if (status !== null && error.code !== "RESPONSE_TOO_LARGE") error.code = "RESPONSE_INTERRUPTED";
			fail(error);
		});
	});
}

function nativeRequest(url, method, body, headers, timeout, options = {}) {
	let host;
	try { host = resolveRectoHostNetwork(); } catch (error) { return Promise.reject(error); }
	if (host) return requestRectoHostNetwork(host, url, method, body, headers, timeout, options);
	return new Promise((resolve, reject) => {
		const p = new URL(url);
		if (p.protocol !== "https:" && p.protocol !== "http:")
			throw new Error(`Unsupported URL protocol: ${p.protocol}`);
		const mod = p.protocol === "https:" ? https : http;
		const h = { ...headers };
		const maxBytes = Number(options.maxBytes) || 0;
		const isStream = body && typeof body.pipe === "function";
		if (body && !isStream && !h["Content-Length"])
			h["Content-Length"] = Buffer.isBuffer(body) ? body.length : Buffer.byteLength(body);
		let settled = false;
		let req;
		let abortHandler;
		let streamErrorHandler;
		let deadlineTimer;
		let responseDecoder;
		let responseStatus = null;
		const requestError = (code, message, cause) => Object.assign(new Error(message), { code, ...(cause ? { cause } : {}) });
		const cleanup = () => {
			if (deadlineTimer) {
				clearTimeout(deadlineTimer);
				deadlineTimer = null;
			}
			if (options.signal && abortHandler) {
				options.signal.removeEventListener("abort", abortHandler);
				abortHandler = null;
			}
			if (isStream && streamErrorHandler && typeof body.removeListener === "function") {
				body.removeListener("error", streamErrorHandler);
				streamErrorHandler = null;
			}
		};
		const fail = (err) => {
			if (settled) return;
			settled = true;
			if (responseStatus !== null) { err.httpStatus = responseStatus; err.responseReceived = true; }
			if (isStream && typeof body.destroy === "function") body.destroy();
			if (responseDecoder && typeof responseDecoder.destroy === "function") responseDecoder.destroy();
			if (req) req.destroy();
			cleanup();
			reject(err);
		};
		const finish = (value) => {
			if (settled) return;
			settled = true;
			cleanup();
			resolve(value);
		};
		if (options.signal && options.signal.aborted) {
			fail(new Error("任务已取消"));
			return;
		}
		const explicitDeadlineMs = Number(options.deadlineMs) || 0;
		if (explicitDeadlineMs > 0) {
			deadlineTimer = setTimeout(() => fail(requestError("REQUEST_DEADLINE_EXCEEDED", "Request deadline exceeded")), explicitDeadlineMs);
			if (typeof deadlineTimer.unref === "function") deadlineTimer.unref();
		}
		req = mod.request({
			hostname: p.hostname, port: p.port || (p.protocol === "https:" ? 443 : 80),
			path: p.pathname + p.search, method, headers: h,
		}, (res) => {
			responseStatus = res.statusCode;
			const chunks = [];
			let total = 0;
			res.on("aborted", () => fail(requestError("RESPONSE_INTERRUPTED", "Response interrupted")));
			res.on("error", error => fail(requestError("RESPONSE_INTERRUPTED", "Response interrupted", error)));
			res.on("close", () => { if (!res.complete) fail(requestError("RESPONSE_INTERRUPTED", "Response interrupted")); });
			res.on("data", (c) => {
				if (settled) return;
				total += c.length;
				if (maxBytes && total > maxBytes) {
					fail(requestError("RESPONSE_TOO_LARGE", `Response too large: ${total} bytes > ${maxBytes} bytes`));
					return;
				}
				chunks.push(c);
			});
			res.on("end", () => {
				if (settled) return;
				const wireBuffer = Buffer.concat(chunks);
				const encoding = String(res.headers["content-encoding"] || "").trim().toLowerCase();
				const finishBuffer = buf => {
					if (settled) return;
					if (maxBytes && buf.length > maxBytes) {
						fail(requestError("RESPONSE_TOO_LARGE", `Response too large: ${buf.length} bytes > ${maxBytes} bytes`));
						return;
					}
					finish({ status: res.statusCode, bodyBuffer: buf, bodyText: buf.toString("utf-8") });
				};
				if (!options.decompressResponse || !encoding || encoding === "identity") {
					finishBuffer(wireBuffer);
					return;
				}
				if (encoding !== "gzip") {
					fail(requestError("RESPONSE_ENCODING_UNSUPPORTED", "Unsupported Content-Encoding"));
					return;
				}
				const decodedChunks = [];
				let decodedBytes = 0;
				responseDecoder = zlib.createGunzip();
				responseDecoder.on("data", chunk => {
					if (settled) return;
					decodedBytes += chunk.length;
					if (maxBytes && decodedBytes > maxBytes) {
						fail(requestError("RESPONSE_TOO_LARGE", `Response too large: ${decodedBytes} bytes > ${maxBytes} bytes`));
						return;
					}
					decodedChunks.push(chunk);
				});
				responseDecoder.on("error", error => fail(requestError("RESPONSE_DECOMPRESSION_FAILED", "Response decompression failed", error)));
				responseDecoder.on("end", () => finishBuffer(Buffer.concat(decodedChunks)));
				responseDecoder.end(wireBuffer);
			});
		});
		abortHandler = () => fail(new Error("任务已取消"));
		if (options.signal) options.signal.addEventListener("abort", abortHandler, { once: true });
		if (timeout) req.setTimeout(timeout, () => fail(requestError("REQUEST_TIMEOUT", "Request timeout")));
		req.on("error", fail);
		if (isStream) {
			streamErrorHandler = fail;
			body.on("error", streamErrorHandler);
			body.pipe(req);
		} else {
			if (body) req.write(body);
			req.end();
		}
	});
}





async function hashFileSha256(filePath, signal = null) {
	return await new Promise((resolve, reject) => {
		const hash = crypto.createHash("sha256");
		const stream = fs.createReadStream(filePath);
		let settled = false;
		const cleanup = () => {
			if (signal) signal.removeEventListener("abort", onAbort);
		};
		const finish = (callback, value) => {
			if (settled) return;
			settled = true;
			cleanup();
			callback(value);
		};
		const onAbort = () => {
			stream.destroy();
			finish(reject, new Error("任务已取消"));
		};
		stream.on("data", chunk => hash.update(chunk));
		stream.on("error", error => finish(reject, error));
		stream.on("end", () => finish(resolve, hash.digest("hex")));
		if (signal) {
			signal.addEventListener("abort", onAbort, { once: true });
			if (signal.aborted) onAbort();
		}
	});
}

